package org.novasos.healthysv2.patient;
import java.time.*; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="allergy",schema="patient") class Allergy {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(nullable=false) private String allergen;@Column(name="allergy_type",length=80) private String type;@Column(columnDefinition="text") private String reaction;@Column(length=30) private String severity;@Column(nullable=false,length=30) private String status;@Column(name="recorded_at",nullable=false) private Instant recordedAt;@Column(name="recorded_by") private UUID recordedBy;protected Allergy(){}static Allergy create(Patient p,String a,String t,String r,String s,String status,Instant at,UUID by){var x=new Allergy();x.patient=p;x.update(a,t,r,s,status,at,by);return x;}void update(String a,String t,String r,String s,String status,Instant at,UUID by){allergen=Patient.required(a);type=Patient.optional(t,true);reaction=Patient.optional(r,false);severity=Patient.optional(s,true);this.status=Patient.normalize(status,"ACTIVE");recordedAt=at==null?Instant.now():at;recordedBy=by;}UUID getId(){return id;}String getAllergen(){return allergen;}String getType(){return type;}String getReaction(){return reaction;}String getSeverity(){return severity;}String getStatus(){return status;}Instant getRecordedAt(){return recordedAt;}UUID getRecordedBy(){return recordedBy;}}
@Entity @Table(name="chronic_disease",schema="patient") class ChronicDisease {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(name="diagnosis_catalog_id") private UUID diagnosisCatalogId;@Column(name="diagnosed_at") private LocalDate diagnosedAt;@Column(nullable=false,length=30) private String status;@Column(columnDefinition="text") private String notes;protected ChronicDisease(){}static ChronicDisease create(Patient p,UUID d,LocalDate at,String s,String n){var x=new ChronicDisease();x.patient=p;x.update(d,at,s,n);return x;}void update(UUID d,LocalDate at,String s,String n){diagnosisCatalogId=d;diagnosedAt=at;status=Patient.normalize(s,"ACTIVE");notes=Patient.optional(n,false);}UUID getId(){return id;}UUID getDiagnosisCatalogId(){return diagnosisCatalogId;}LocalDate getDiagnosedAt(){return diagnosedAt;}String getStatus(){return status;}String getNotes(){return notes;}}
@Entity @Table(name="medical_history",schema="patient") class MedicalHistory {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(nullable=false,length=500) private String condition;@Column(name="diagnosed_at") private LocalDate diagnosedAt;@Column(name="resolved_at") private LocalDate resolvedAt;@Column(columnDefinition="text") private String notes;protected MedicalHistory(){}static MedicalHistory create(Patient p,String c,LocalDate d,LocalDate r,String n){var x=new MedicalHistory();x.patient=p;x.update(c,d,r,n);return x;}void update(String c,LocalDate d,LocalDate r,String n){if(d!=null&&r!=null&&r.isBefore(d))throw new IllegalArgumentException("Invalid history dates");condition=Patient.required(c);diagnosedAt=d;resolvedAt=r;notes=Patient.optional(n,false);}UUID getId(){return id;}String getCondition(){return condition;}LocalDate getDiagnosedAt(){return diagnosedAt;}LocalDate getResolvedAt(){return resolvedAt;}String getNotes(){return notes;}}
@Entity @Table(name="surgical_history",schema="patient") class SurgicalHistory {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(name="procedure_name",nullable=false,length=500) private String procedureName;@Column(name="procedure_date") private LocalDate procedureDate;@Column(name="organization_id") private UUID organizationId;@Column(columnDefinition="text") private String notes;protected SurgicalHistory(){}static SurgicalHistory create(Patient p,String n,LocalDate d,UUID o,String notes){var x=new SurgicalHistory();x.patient=p;x.update(n,d,o,notes);return x;}void update(String n,LocalDate d,UUID o,String notes){procedureName=Patient.required(n);procedureDate=d;organizationId=o;this.notes=Patient.optional(notes,false);}UUID getId(){return id;}String getProcedureName(){return procedureName;}LocalDate getProcedureDate(){return procedureDate;}UUID getOrganizationId(){return organizationId;}String getNotes(){return notes;}}
@Entity @Table(name="family_history",schema="patient") class FamilyHistory {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(length=100) private String relationship;@Column(nullable=false,length=500) private String condition;@Column(columnDefinition="text") private String notes;protected FamilyHistory(){}static FamilyHistory create(Patient p,String r,String c,String n){var x=new FamilyHistory();x.patient=p;x.update(r,c,n);return x;}void update(String r,String c,String n){relationship=Patient.optional(r,false);condition=Patient.required(c);notes=Patient.optional(n,false);}UUID getId(){return id;}String getRelationship(){return relationship;}String getCondition(){return condition;}String getNotes(){return notes;}}
@Entity @Table(name="disability",schema="patient") class Disability {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(nullable=false,length=100) private String type;@Column(columnDefinition="text") private String description;@Column(name="start_date") private LocalDate startDate;@Column(nullable=false,length=30) private String status;protected Disability(){}static Disability create(Patient p,String t,String d,LocalDate s,String status){var x=new Disability();x.patient=p;x.update(t,d,s,status);return x;}void update(String t,String d,LocalDate s,String status){type=Patient.required(t).toUpperCase();description=Patient.optional(d,false);startDate=s;this.status=Patient.normalize(status,"ACTIVE");}UUID getId(){return id;}String getType(){return type;}String getDescription(){return description;}LocalDate getStartDate(){return startDate;}String getStatus(){return status;}}
@Entity @Table(name="patient_note",schema="patient") class PatientNote {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(name="author_person_id") private UUID authorPersonId;@Column(name="note_type",length=50) private String type;@Column(nullable=false,columnDefinition="text") private String content;@Column(name="created_at",nullable=false) private Instant createdAt;protected PatientNote(){}static PatientNote create(Patient p,UUID a,String t,String c,Instant at){var x=new PatientNote();x.patient=p;x.update(a,t,c);x.createdAt=at==null?Instant.now():at;return x;}void update(UUID a,String t,String c){authorPersonId=a;type=Patient.optional(t,true);content=Patient.required(c);}UUID getId(){return id;}UUID getAuthorPersonId(){return authorPersonId;}String getType(){return type;}String getContent(){return content;}Instant getCreatedAt(){return createdAt;}}
@Entity @Table(name="patient_flag",schema="patient") class PatientFlag {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id") private Patient patient;@Column(name="flag_type",nullable=false,length=50) private String type;@Column(nullable=false) private String label;@Column(length=30) private String severity;@Column(nullable=false) private boolean active;@Column(name="created_at",nullable=false) private Instant createdAt;protected PatientFlag(){}static PatientFlag create(Patient p,String t,String l,String s,boolean a,Instant at){var x=new PatientFlag();x.patient=p;x.update(t,l,s,a);x.createdAt=at==null?Instant.now():at;return x;}void update(String t,String l,String s,boolean a){type=Patient.required(t).toUpperCase();label=Patient.required(l);severity=Patient.optional(s,true);active=a;}UUID getId(){return id;}String getType(){return type;}String getLabel(){return label;}String getSeverity(){return severity;}boolean isActive(){return active;}Instant getCreatedAt(){return createdAt;}}
@Entity @Table(name="emergency_profile",schema="patient") class EmergencyProfile {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="patient_id",unique=true) private Patient patient;@Column(name="emergency_code",unique=true,length=100) private String emergencyCode;@Column(name="blood_group_visible",nullable=false) private boolean bloodGroupVisible;@Column(name="allergies_visible",nullable=false) private boolean allergiesVisible;@Column(name="conditions_visible",nullable=false) private boolean conditionsVisible;@Column(name="medications_visible",nullable=false) private boolean medicationsVisible;@Column(name="emergency_contact_visible",nullable=false) private boolean emergencyContactVisible;@Column(nullable=false) private boolean active;protected EmergencyProfile(){}static EmergencyProfile create(Patient p,String c,boolean b,boolean a,boolean co,boolean m,boolean e,boolean active){var x=new EmergencyProfile();x.patient=p;x.update(c,b,a,co,m,e,active);return x;}void update(String c,boolean b,boolean a,boolean co,boolean m,boolean e,boolean active){emergencyCode=Patient.optional(c,false);bloodGroupVisible=b;allergiesVisible=a;conditionsVisible=co;medicationsVisible=m;emergencyContactVisible=e;this.active=active;}UUID getId(){return id;}String getEmergencyCode(){return emergencyCode;}boolean isBloodGroupVisible(){return bloodGroupVisible;}boolean isAllergiesVisible(){return allergiesVisible;}boolean isConditionsVisible(){return conditionsVisible;}boolean isMedicationsVisible(){return medicationsVisible;}boolean isEmergencyContactVisible(){return emergencyContactVisible;}boolean isActive(){return active;}}
